// rotateEndpointSecret gives an endpoint a new signing secret. The answer includes it. The old secret keeps signing the
// deliveries for 24 hours.
func (s *Server) rotateEndpointSecret(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	ep, err := s.store.RotateWebhookSecret(p.OrgID, r.PathValue("id"), webhooks.NewSecret(), s.clock.Now())
	if err != nil {
		s.storeError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, ep)
}

