package webhooks_test

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
	"example.com/tally/internal/webhooks"
)

func TestSign(t *testing.T) {
	// HMAC-SHA256("key", "The quick brown fox jumps over the lazy dog")
	const want = "f7bc83f430538424b13298e6aa6fb143ef4d59a14946175997479dbc2d1a3cd8"
	if got := webhooks.Sign("key", []byte("The quick brown fox jumps over the lazy dog")); got != want {
		t.Fatalf("Sign = %s", got)
	}
}

func TestSignatureHeader(t *testing.T) {
	body := []byte(`{"id":"evt_1"}`)
	at := time.Unix(1_700_000_000, 999)
	header := webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, at, body)
	want := fmt.Sprintf("t=1700000000,v1=%s,v1=%s",
		webhooks.Sign("whsec_new", []byte("1700000000."+string(body))),
		webhooks.Sign("whsec_old", []byte("1700000000."+string(body))))
	if header != want {
		t.Fatalf("SignatureHeader = %q, want %q", header, want)
	}
	if err := webhooks.Verify(body, header, []string{"whsec_old"}, 0, at); err != nil {
		t.Fatal(err)
	}
	if got := webhooks.SignatureHeader([]string{"whsec_only"}, at, body); strings.Count(got, ",v1=") != 1 {
		t.Fatalf("one secret: %q", got)
	}
}

func TestVerify(t *testing.T) {
	body := []byte(`{"id":"evt_1","type":"invoice.paid"}`)
	const ts = 1_700_000_000
	now := time.Unix(ts, 0)
	sig := func(secret string, stamp int64) string {
		return webhooks.Sign(secret, []byte(fmt.Sprintf("%d.%s", stamp, body)))
	}
	five := 5 * time.Minute
	cases := []struct {
		name    string
		header  string
		secrets []string
		tol     time.Duration
		now     time.Time
		want    error // nil: Verify must succeed
	}{
		{"valid", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now, nil},
		{"spaces, order and unknown keys", fmt.Sprintf(" v1=%s , v0=abc ,t = %d ", sig("whsec_a", ts), ts), []string{"whsec_a"}, 0, now, nil},
		{"second v1 matches the second secret", fmt.Sprintf("t=%d,v1=%s,v1=%s", ts, sig("whsec_x", ts), sig("whsec_b", ts)), []string{"whsec_a", "whsec_b"}, 0, now, nil},
		{"the first secret still matches", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_new", "whsec_a"}, 0, now, nil},
		{"exactly the default tolerance in the past", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now.Add(five), nil},
		{"exactly the default tolerance in the future", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now.Add(-five), nil},
		{"tolerance given", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, time.Minute, now.Add(time.Minute), nil},
		{"too old", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now.Add(five + time.Second), webhooks.ErrTimestampTolerance},
		{"too new", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now.Add(-five - time.Second), webhooks.ErrTimestampTolerance},
		{"outside a given tolerance", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, time.Minute, now.Add(2 * time.Minute), webhooks.ErrTimestampTolerance},
		{"empty", "", []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"blank", "  ", []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"pair without =", fmt.Sprintf("t=%d,v1", ts), []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"empty pair", fmt.Sprintf("t=%d,,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"timestamp not an integer", fmt.Sprintf("t=%d.5,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"empty timestamp", "t=,v1=abc", []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"no timestamp", "v1=" + sig("whsec_a", ts), []string{"whsec_a"}, 0, now, webhooks.ErrNoTimestamp},
		{"no signature", fmt.Sprintf("t=%d", ts), []string{"whsec_a"}, 0, now, webhooks.ErrNoSignature},
		{"only unknown keys", fmt.Sprintf("t=%d,v0=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now, webhooks.ErrNoSignature},
		{"signature of another timestamp", fmt.Sprintf("t=%d,v1=%s", ts+1, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now, webhooks.ErrSignatureMismatch},
		{"signature of another secret", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_b", ts)), []string{"whsec_a"}, 0, now, webhooks.ErrSignatureMismatch},
		{"no secrets", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), nil, 0, now, webhooks.ErrSignatureMismatch},
		{"empty secret does not count", fmt.Sprintf("t=%d,v1=%s", ts, sig("", ts)), []string{""}, 0, now, webhooks.ErrSignatureMismatch},
		{"timestamp checked before signature", fmt.Sprintf("t=%d", ts), []string{"whsec_a"}, 0, now.Add(time.Hour), webhooks.ErrTimestampTolerance},
		{"malformed before timestamp", "t=1,v1", []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			err := webhooks.Verify(body, c.header, c.secrets, c.tol, c.now)
			if c.want == nil {
				if err != nil {
					t.Fatalf("Verify = %v", err)
				}
				return
			}
			if !errors.Is(err, c.want) {
				t.Fatalf("Verify = %v, want %v", err, c.want)
			}
		})
	}
}

func TestCheckURL(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	for _, ok := range []string{"https://hooks.acme.example/tally", "https://93.184.216.34:8443/in"} {
		if err := e.Webhooks.CheckURL(ctx, ok); err != nil {
			t.Errorf("CheckURL(%q) = %v", ok, err)
		}
	}
	for _, bad := range []string{"", "hooks.acme.example/x", "ftp://hooks.acme.example/", "https:///x", "https://unknown.example/x"} {
		if err := e.Webhooks.CheckURL(ctx, bad); !errors.Is(err, webhooks.ErrInvalidURL) {
			t.Errorf("CheckURL(%q) = %v, want ErrInvalidURL", bad, err)
		}
	}
	if err := webhooks.CheckEvents([]string{"invoice.paid", "*"}); err != nil {
		t.Error(err)
	}
	for _, bad := range [][]string{nil, {"invoice.eaten"}} {
		if err := webhooks.CheckEvents(bad); !errors.Is(err, webhooks.ErrInvalidEvents) {
			t.Errorf("CheckEvents(%v) = %v", bad, err)
		}
	}
}

func TestPublishAndDeliver(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	now := e.Clock.Now()
	all, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_a", Enabled: true}, now)
	paid, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/paid", Events: []string{"invoice.paid"}, Secret: "whsec_b", Enabled: true}, now)
	_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/off", Events: []string{"*"}, Secret: "whsec_c", Enabled: false}, now)
	_, _ = e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Globex.ID, URL: "https://hooks.globex.example/", Events: []string{"*"}, Secret: "whsec_d", Enabled: true}, now)

	if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
		t.Fatal(err)
	}
	n, err := e.Webhooks.RunDue(ctx)
	if err != nil || n != 1 {
		t.Fatalf("RunDue = %d, %v (only the endpoint for every event wants customer.created)", n, err)
	}
	reqs := e.HTTP.Requests()
	if len(reqs) != 1 || reqs[0].URL != all.URL || reqs[0].Method != http.MethodPost {
		t.Fatalf("requests = %+v", reqs)
	}
	if err := webhooks.Verify(reqs[0].Body, reqs[0].Header.Get("Tally-Signature"), []string{"whsec_a"}, 0, e.Clock.Now()); err != nil {
		t.Fatalf("signature %q: %v", reqs[0].Header.Get("Tally-Signature"), err)
	}
	var body webhooks.Body
	if err := json.Unmarshal(reqs[0].Body, &body); err != nil || body.Type != "customer.created" || reqs[0].Header.Get("Tally-Event-Id") != body.ID {
		t.Fatalf("body = %s (%v)", reqs[0].Body, err)
	}
	ds := e.Store.Deliveries(e.Acme.ID, all.ID)
	if len(ds) != 1 || ds[0].Status != store.DeliverySucceeded || ds[0].Attempts != 1 || ds[0].ResponseStatus != 200 {
		t.Fatalf("deliveries = %+v", ds)
	}

	e.HTTP.Respond = func(r apitest.Request) (int, error) { return http.StatusInternalServerError, nil }
	_ = e.Webhooks.Publish(ctx, e.Acme.ID, "invoice.paid", map[string]string{"invoice_id": "in_1"})
	if n, _ := e.Webhooks.RunDue(ctx); n != 2 {
		t.Fatalf("RunDue = %d, want 2", n)
	}
	for _, ep := range []store.WebhookEndpoint{all, paid} {
		ds := e.Store.Deliveries(e.Acme.ID, ep.ID)
		last := ds[len(ds)-1]
		if last.Status != store.DeliveryFailed || last.ResponseStatus != 500 || last.Error == "" {
			t.Fatalf("delivery to %s = %+v", ep.URL, last)
		}
	}
	if n, _ := e.Webhooks.RunDue(ctx); n != 0 {
		t.Fatalf("a failed delivery was sent again: %d", n)
	}
}

// TestRotatedSecretSigning checks which secrets sign deliveries across rotations: the current secret and, for 24 hours after a
// rotation, the previous one; a rotation within those hours drops the older one at once.
func TestRotatedSecretSigning(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_0", Enabled: true}, e.Clock.Now())
	rotate := func(secret string) {
		t.Helper()
		if _, err := e.Store.RotateWebhookSecret(e.Acme.ID, ep.ID, secret, e.Clock.Now()); err != nil {
			t.Fatal(err)
		}
	}
	// send publishes an event, delivers it and returns the header and body of the delivery.
	send := func() (string, []byte) {
		t.Helper()
		if err := e.Webhooks.Publish(ctx, e.Acme.ID, "customer.created", map[string]string{"id": "cus_1"}); err != nil {
			t.Fatal(err)
		}
		if n, err := e.Webhooks.RunDue(ctx); err != nil || n != 1 {
			t.Fatalf("RunDue = %d, %v", n, err)
		}
		reqs := e.HTTP.Requests()
		last := reqs[len(reqs)-1]
		return last.Header.Get("Tally-Signature"), last.Body
	}
	// expect checks the header's v1 entries are signed by exactly the secrets given, in order.
	expect := func(header string, body []byte, secrets ...string) {
		t.Helper()
		if n := strings.Count(header, ",v1="); n != len(secrets) {
			t.Fatalf("header %q has %d v1 entries, want %d", header, n, len(secrets))
		}
		for _, s := range secrets {
			if err := webhooks.Verify(body, header, []string{s}, 0, e.Clock.Now()); err != nil {
				t.Fatalf("header %q with %s: %v", header, s, err)
			}
		}
	}

	// Before any rotation only the original secret signs.
	h, body := send()
	expect(h, body, "whsec_0")

	rotate("whsec_1")
	h, body = send()
	expect(h, body, "whsec_1", "whsec_0")

	e.Clock.Advance(24*time.Hour - time.Second)
	h, body = send()
	expect(h, body, "whsec_1", "whsec_0")

	e.Clock.Advance(time.Second)
	h, body = send()
	expect(h, body, "whsec_1")
	if err := webhooks.Verify(body, h, []string{"whsec_0"}, 0, e.Clock.Now()); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Fatalf("expired secret still signs: %v", err)
	}

	// A rotation a day later keeps the previous secret for another 24 hours.
	rotate("whsec_2")
	h, body = send()
	expect(h, body, "whsec_2", "whsec_1")

	// Rotating again within the 24 hours drops whsec_1 at once.
	e.Clock.Advance(time.Hour)
	rotate("whsec_3")
	h, body = send()
	expect(h, body, "whsec_3", "whsec_2")
	if err := webhooks.Verify(body, h, []string{"whsec_1"}, 0, e.Clock.Now()); !errors.Is(err, webhooks.ErrSignatureMismatch) {
		t.Fatalf("dropped secret still signs: %v", err)
	}
}

