		{"valid", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now, nil},
		{"spaces, order and unknown keys", fmt.Sprintf(" v1=%s , v0=abc ,t = %d ", sig("whsec_a", ts), ts), []string{"whsec_a"}, 0, now, nil},
		{"second v1 matches the second secret", fmt.Sprintf("t=%d,v1=%s,v1=%s", ts, sig("whsec_x", ts), sig("whsec_b", ts)), []string{"whsec_a", "whsec_b"}, 0, now, nil},
		{"the first secret still matches", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_new", "whsec_a"}, 0, now, nil},
		{"exactly the default tolerance in the past", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now.Add(five), nil},
		{"exactly the default tolerance in the future", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now.Add(-five), nil},
		{"tolerance given", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, time.Minute, now.Add(time.Minute), nil},
		{"too old", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now.Add(five + time.Second), webhooks.ErrTimestampTolerance},
		{"too new", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now.Add(-five - time.Second), webhooks.ErrTimestampTolerance},
		{"outside a given tolerance", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, time.Minute, now.Add(2 * time.Minute), webhooks.ErrTimestampTolerance},
		{"empty", "", []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"blank", "  ", []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"pair without =", fmt.Sprintf("t=%d,v1", ts), []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"empty pair", fmt.Sprintf("t=%d,,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"timestamp not an integer", fmt.Sprintf("t=%d.5,v1=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"empty timestamp", "t=,v1=abc", []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
		{"no timestamp", "v1=" + sig("whsec_a", ts), []string{"whsec_a"}, 0, now, webhooks.ErrNoTimestamp},
		{"no signature", fmt.Sprintf("t=%d", ts), []string{"whsec_a"}, 0, now, webhooks.ErrNoSignature},
		{"only unknown keys", fmt.Sprintf("t=%d,v0=%s", ts, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now, webhooks.ErrNoSignature},
		{"signature of another timestamp", fmt.Sprintf("t=%d,v1=%s", ts+1, sig("whsec_a", ts)), []string{"whsec_a"}, 0, now, webhooks.ErrSignatureMismatch},
		{"signature of another secret", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_b", ts)), []string{"whsec_a"}, 0, now, webhooks.ErrSignatureMismatch},
		{"no secrets", fmt.Sprintf("t=%d,v1=%s", ts, sig("whsec_a", ts)), nil, 0, now, webhooks.ErrSignatureMismatch},
		{"empty secret does not count", fmt.Sprintf("t=%d,v1=%s", ts, sig("", ts)), []string{""}, 0, now, webhooks.ErrSignatureMismatch},
		{"timestamp checked before signature", fmt.Sprintf("t=%d", ts), []string{"whsec_a"}, 0, now.Add(time.Hour), webhooks.ErrTimestampTolerance},
		{"malformed before timestamp", "t=1,v1", []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			err := webhooks.Verify(body, c.header, c.secrets, c.tol, c.now)
			if c.want == nil {
				if err != nil {
					t.Fatalf("Verify = %v", err)
				}
				return
			}
			if !errors.Is(err, c.want) {
				t.Fatalf("Verify = %v, want %v", err, c.want)
			}
		})
	}
}

